update tb_take_orders
order_id = #{orderId}, user_id = #{userId}, create_time = #{createTime}, image = #{image}, deleted = #{deleted}, status = #{status}, delivery_time = #{deliveryTime}, cancel_time = #{cancelTime}, cancel_reason = #{cancelReason},
where id = #{id}
